html:
{%- set ar = (frappe.local.lang or "en").startswith("ar") -%}
<div class="rq-payslip" dir="{{ 'rtl' if ar else 'ltr' }}">
<style>
.rq-payslip { font-size: 12px; }
.rq-payslip h2 { margin: 0 0 4px; font-size: 18px; }
.rq-payslip .muted { color: #6b7280; }
.rq-payslip .note { font-size: 10px; }
.rq-payslip table { width: 100%; border-collapse: collapse; margin-top: 10px; }
.rq-payslip th, .rq-payslip td { border: 1px solid #d1d5db; padding: 5px 8px; text-align: start; }
.rq-payslip td.num, .rq-payslip th.num { text-align: end; white-space: nowrap; }
.rq-payslip .total td, .rq-payslip .total th { font-weight: 700; background: #f3f4f6; }
.rq-payslip .net { margin-top: 12px; font-size: 15px; font-weight: 700; }
.rq-payslip .sign { margin-top: 40px; display: flex; justify-content: space-between; }
</style>
<h2>{{ _("Salary Slip") }}</h2>
<div class="muted">{{ doc.company }} · {{ frappe.format(doc.from_date, {"fieldtype": "Date"}) }} – {{ frappe.format(doc.to_date, {"fieldtype": "Date"}) }}</div>
<table>
<tr><th>{{ _("Employee") }}</th><td>{{ doc.employee_name }} ({{ doc.employee }})</td>
<th>{{ _("Department") }}</th><td>{{ _(doc.department) if doc.department else "" }}</td></tr>
<tr><th>{{ _("Designation") }}</th><td>{{ _(doc.designation) if doc.designation else "" }}</td>
<th>{{ _("Paid Days") }}</th><td>{{ doc.payment_days | float }} / {{ doc.total_days | float }}</td></tr>
</table>
<table>
<tr><th>{{ _("Earnings") }}</th><th class="num">{{ _("Amount") }}</th><th>{{ _("Deductions") }}</th><th class="num">{{ _("Amount") }}</th></tr>
{%- set n = [doc.earnings|length, doc.deductions|length]|max -%}
{%- for i in range(n) -%}
{%- set e = doc.earnings[i] if i < doc.earnings|length else None -%}
{%- set d = doc.deductions[i] if i < doc.deductions|length else None -%}
<tr><td>{{ _(e.component) if e else "" }}{% if e and e.note %}<div class="muted note">{{ e.note | e }}</div>{% endif %}</td><td class="num">{{ frappe.format(e.amount, {"fieldtype": "Currency", "options": "currency"}, doc) if e else "" }}</td>
<td>{{ _(d.component) if d else "" }}{% if d and d.note %}<div class="muted note">{{ d.note | e }}</div>{% endif %}</td><td class="num">{{ frappe.format(d.amount, {"fieldtype": "Currency", "options": "currency"}, doc) if d else "" }}</td></tr>
{%- endfor %}
<tr class="total"><td>{{ _("Gross Pay") }}</td><td class="num">{{ doc.get_formatted("gross") }}</td>
<td>{{ _("Total Deductions") }}</td><td class="num">{{ doc.get_formatted("total_deductions") }}</td></tr>
</table>
<div class="net">{{ _("Net Pay") }}: {{ doc.get_formatted("net_pay") }}</div>
<div class="sign"><span>{{ _("Employee signature") }}: ____________</span><span>{{ _("Approved by") }}: ____________</span></div>
</div>
